import pytest


def first_or(xs: list[int], default: int) -> int:
    """Return the first element of xs, or default if xs is empty."""
    if xs:
        return xs[0]
    return default


def test_first_or_nonempty() -> None:
    assert first_or([7, 8, 9], 0) == 7


def test_first_or_single() -> None:
    assert first_or([5], -1) == 5


def test_first_or_empty() -> None:
    assert first_or([], 42) == 42


def test_first_or_falsy_first_element() -> None:
    # A first element of 0 must be returned, not replaced by the default.
    assert first_or([0, 1], 99) == 0


def test_first_or_negative_first_element() -> None:
    assert first_or([-3, 4], 10) == -3


def test_first_or_does_not_mutate() -> None:
    xs = [1, 2, 3]
    first_or(xs, 0)
    assert xs == [1, 2, 3]


@pytest.mark.parametrize(
    ("xs", "default", "expected"),
    [
        ([], 0, 0),
        ([], -5, -5),
        ([1], 0, 1),
        ([2, 1], 0, 2),
        ([0], 7, 0),
    ],
)
def test_first_or_parametrized(xs: list[int], default: int, expected: int) -> None:
    assert first_or(xs, default) == expected

